// Writes tests/fixtures/bundle.generated.ts: every report-2 document of the contract bundle as an object literal
// `satisfies Report2`, one named export per document. A module has one default export, so each document gets a name
// from its file. The form is `satisfies` without `as const`: `as const` makes every array a readonly tuple, which the
// shapes do not admit.
//   node emit_bundle.js
'use strict';
const fs = require('fs');
const path = require('path');
const { FIXTURES, files, read } = require('./documents');

const BUNDLE = path.join(FIXTURES, 'contract', 'report-2');
const out = [
  '// GENERATED by tools/schema/node/emit_bundle.js from tests/fixtures/contract/report-2/: do not edit.',
  "import type { Report2 } from '../../types/lockrot-report-2';",
  '',
];
for (const file of files(BUNDLE)) {
  const name = 'd_' + path.relative(BUNDLE, file).replace(/\.json(\.gz)?$/, '').replace(/[^A-Za-z0-9]+/g, '_');
  out.push(`export const ${name} = ${read(file).trim()} satisfies Report2;`, '');
}
fs.writeFileSync(path.join(FIXTURES, 'bundle.generated.ts'), out.join('\n'));
